result = []

for item in _items:
    for segment in item["json"]["data"]:
        value = segment["value"]
        start = segment["start"]
        end = segment["end"]

        duration_str = str(start) + "-" + str(end)

        result.append({
            "json": {
                duration_str: value.strip()
            }
        })

return result
